SINA_SMART["embryo1-git"] = {"lecture":"embryo1-git","title":"Development of the digestive system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"embryo1-git:e0","text":"Primitive gut: stomodeum → pharynx → foregut → midgut → hindgut → cloaca.","topic":"The primitive gut","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e1","text":"Endoderm: epithelium and glands; splanchnic mesoderm: muscle and connective tissue.","topic":"The primitive gut","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e2","text":"Oesophageal atresia: 90% with TOF; polyhydramnios; NG tube cannot pass.","topic":"Foregut: oesophagus, stomach, duodenum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e3","text":"Stomach: grows (greater curvature), descends C2 → T11, rotates 90° clockwise, shifts left.","topic":"Foregut: oesophagus, stomach, duodenum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e4","text":"Duodenum becomes retroperitoneal; lumen obliterated weeks 5-6 then recanalised.","topic":"Foregut: oesophagus, stomach, duodenum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e5","text":"Week 4 buds: hepatic diverticulum, ventral and dorsal pancreatic buds.","topic":"Liver, pancreas and spleen","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e6","text":"Fetal liver: haematopoiesis week 6-birth, bile from week 12; insulin from week 10.","topic":"Liver, pancreas and spleen","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e7","text":"Spleen: mesoderm in the dorsal mesogastrium, week 5.","topic":"Liver, pancreas and spleen","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e8","text":"Midgut: herniates week 6, rotates 270° anticlockwise, returns by week 10 (caecum last).","topic":"Midgut: herniation and rotation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e9","text":"Meckel's: 2%, ~2 feet from ileocaecal junction, 2 inches, M:F 2:1.","topic":"Midgut: herniation and rotation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-git:e10","text":"Omphalocele: covered sac; gastroschisis: uncovered; Hirschsprung: neural crest defect.","topic":"Hindgut and congenital anomalies","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"xz03rw":"a","1ta6dp6":"a","1voeqm4":"a","blxhlq":"a","13dova0":"a","12f6pzy":"a","hn1pl2":"a","rfl2oo":"a","quuxv1":"a","1cavd6s":"a","1u7mlgt":"a","ai0v08":"a","1oro3fj":"a","1igonkq":"a","b8zvou":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"embryo1-git:e0":{"s":0,"u":["Primitive gut: stomodeum → pharynx → foregut → midgut → hindgut → cloaca.","Sequence: stomodeum → pharynx → foregut → midgut → hindgut → cloaca.","Folding incorporates the yolk sac into the embryo as the primitive gut , closed cranially by the oropharyngeal membrane (separating the ectoderm-lined stomodeum from the endoderm-lined pharynx) and caudally by the cloacal (proctodeal) membrane ."],"dp":[]},"embryo1-git:e1":{"s":0,"u":["Endoderm: epithelium and glands; splanchnic mesoderm: muscle and connective tissue.","The endoderm forms the epithelium and glands; the splanchnic mesoderm forms the muscle and connective tissue."],"dp":[]},"embryo1-git:e2":{"s":1,"u":["Oesophageal atresia: 90% with TOF; polyhydramnios; NG tube cannot pass.","Oesophageal atresia : 90% with a tracheo-oesophageal fistula ; the fetus cannot swallow amniotic fluid (polyhydramnios); the newborn rejects feeds and an NG tube cannot be passed."],"dp":[]},"embryo1-git:e3":{"s":1,"u":["Stomach: grows (greater curvature), descends C2 → T11, rotates 90° clockwise, shifts left.","The stomach starts as a tube; its dorsal border grows faster ( greater curvature ) than the ventral (lesser curvature).","It descends (from C2 in week 4 to T11 by week 12), tilts to an oblique position, rotates 90° clockwise around its long axis (left vagus to the front, right vagus to the back) and shifts left with the dorsal mesentery."],"dp":[]},"embryo1-git:e4":{"s":1,"u":["Duodenum becomes retroperitoneal; lumen obliterated weeks 5-6 then recanalised.","The duodenum (week 4, from the caudal foregut and cranial midgut) forms a C-loop, is pulled right and becomes retroperitoneal ; its lumen is obliterated in weeks 5-6 and recanalised by the end of the embryonic period."],"dp":[]},"embryo1-git:e5":{"s":2,"u":["Week 4 buds: hepatic diverticulum, ventral and dorsal pancreatic buds.","In week 4 three buds grow from the duodenum: the hepatic diverticulum and the ventral and dorsal pancreatic buds ."],"dp":[]},"embryo1-git:e6":{"s":2,"u":["Fetal liver: haematopoiesis week 6-birth, bile from week 12; insulin from week 10.","Fetal liver: haematopoiesis from week 6 to birth, albumin from week 5, bile from week 12 (dark-green meconium from the 4th month), glycogen late.","The ventral bud rotates behind the duodenum to fuse with the dorsal bud; insulin secretion starts around week 10."],"dp":[]},"embryo1-git:e7":{"s":2,"u":["Spleen: mesoderm in the dorsal mesogastrium, week 5.","The spleen is mesodermal, a mass of mesenchyme in the dorsal mesogastrium from week 5; the stomach's rotation carries it to the left, linked by the gastrosplenic and splenorenal ligaments."],"dp":[]},"embryo1-git:e8":{"s":3,"u":["Midgut: herniates week 6, rotates 270° anticlockwise, returns by week 10 (caecum last).","In week 6 the growing loop and the large liver leave no room, so the midgut herniates into the umbilical cord ( physiological hernia ); it returns by week 10 , the caecum last.","Taking the caecum as a landmark, the gut rotates 270° anticlockwise : 90° during herniation, 180° during the return, then the caecum descends to the right iliac fossa."],"dp":[{"h":"Malrotation and the green vomit emergency","t":"If the midgut does not complete its 270° rotation, the caecum stays high and the small bowel mesentery keeps a narrow base, anchored only near the superior mesenteric artery. That short pivot lets the whole midgut twist around the artery: midgut volvulus . The duodenum is kinked, so a baby vomits bile (green) , and the twisted vessels can kill the entire midgut within hours. That is why bilious vomiting in a newborn is treated as a surgical emergency until proven otherwise, and why the embryology of rotation matters on the ward. Source: the lecture's midgut rotation and non-rotation anomalies."}]},"embryo1-git:e9":{"s":3,"u":["Meckel's: 2%, ~2 feet from ileocaecal junction, 2 inches, M:F 2:1.","A persistent proximal vitelline duct is Meckel's diverticulum : the 'rule of 2s', about 2% of people, about 2 feet (60 cm) from the ileocaecal junction, about 2 inches long, male to female 2:1."],"dp":[]},"embryo1-git:e10":{"s":4,"u":["Omphalocele: covered sac; gastroschisis: uncovered; Hirschsprung: neural crest defect.","Anomalies : omphalocele (about 1 in 5000; gut, even liver, in a membrane-covered sac at the umbilicus; 50% with other anomalies), umbilical hernia (covered by skin, mostly omentum, often closes as the linea alba strengthens), gastroschisis (defect in the abdominal wall beside the umbilicus, no covering), non-rotation (small bowel on the right, colon on the left) with risk of volvulus , situs inversus, intussusception, atresias of jejunum, ileum or colon, subhepatic caecum, Hirschsprung disease (congenital megacolon: absent parasympathetic ganglia from failed neural crest migration) and anal atresia / imperforate anus (about 1 in 5000, more in males, 90% with an external fistula)."],"dp":[]}},"meta":{"xz03rw":{"a":"recall","vg":"embryo1-git:e0/recall/1"},"1ta6dp6":{"a":"recall","vg":"embryo1-git:e2/recall/1"},"1voeqm4":{"a":"recall","vg":"embryo1-git:e2/recall/1"},"blxhlq":{"a":"recall","vg":"embryo1-git:e3/recall/1"},"13dova0":{"a":"recall","vg":"embryo1-git:e3/recall/2"},"12f6pzy":{"a":"recall","vg":"embryo1-git:e4/recall/1"},"hn1pl2":{"a":"recall","vg":"embryo1-git:e5/recall/1"},"rfl2oo":{"a":"recall","vg":"embryo1-git:e6/recall/1"},"quuxv1":{"a":"recall","vg":"embryo1-git:e7/recall/1"},"1cavd6s":{"a":"recall","vg":"embryo1-git:e8/recall/1"},"1u7mlgt":{"a":"recall","vg":"embryo1-git:e8/recall/2"},"ai0v08":{"a":"recall","vg":"embryo1-git:e9/recall/1"},"1oro3fj":{"a":"recall","vg":"embryo1-git:e0/recall/2"},"1igonkq":{"a":"recall","vg":"embryo1-git:e10/recall/1"},"b8zvou":{"a":"recall","vg":"embryo1-git:e10/recall/2"}},"explRev":"da2d450329c7"};
